def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate pressure
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Baseline bids: tie to supply realism
    # If supply is low (~15), water is scarce: raise bids; if high (~25), lower a bit.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Pressure from opponent yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify Cindy/Bob style by their previous bid if present
    def prev_bid_for(agent_id):
        o = opponents_status.get(agent_id, None)
        if not o:
            return None
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            return None
        try:
            return float(b)
        except Exception:
            return None

    cindy_bid = prev_bid_for('Cindy')
    bob_bid = prev_bid_for('Bob')

    # Core strategy:
    # - If someone previously bid extremely high (>= 0.85 salary), we avoid matching exactly but bid enough.
    # - If our HP is low, we overbid to secure water.
    # - If Cindy was the high bidder, we slightly undercut her typical level.
    target = None

    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp > 3.0 and my_no_water_days <= 1:
            # safe: mid-high to beat most but not chase the ceiling
            target = DAILY_SALARY * (0.28 + 0.35 * scarcity)
        else:
            # critical: overbid
            target = DAILY_SALARY * (0.85 + 0.1 * scarcity)
    else:
        # Otherwise, use a supply-adjusted mid bid, nudged above Bob if he was active
        base = DAILY_SALARY * (0.48 + 0.22 * scarcity)
        if bob_bid is not None and bob_bid > 0:
            # bid just above Bob's yesterday bid if it seems influential
            target = max(base, bob_bid * 1.05)
        else:
            target = base

    # If Cindy bid was high, undercut her a bit (but still respect our target)
    if cindy_bid is not None and cindy_bid > 0:
        # If Cindy was far above, don't match; if close, try to beat.
        if cindy_bid >= DAILY_SALARY * 0.85:
            target = min(target, cindy_bid * 0.92) if my_hp > 3.0 else max(target, cindy_bid * 0.98)
        else:
            # If she wasn't extreme, still try to be near her level
            target = max(target, cindy_bid * 0.95)

    # Clamp to budget and non-negative
    target = max(0.0, float(target))
    bid = min(my_budget, target)

    # If budget is too low, spend what we can
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_prev = 0.0
    cindy_prev = None
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid > strong_prev:
                    strong_prev = bid
                if agent_id == 'Cindy':
                    cindy_prev = bid

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units <= 1.2:
        scarcity = 3
    elif units <= 1.8:
        scarcity = 2
    else:
        scarcity = 1

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    else:
        urgency = 1

    reference = strong_prev
    if cindy_prev is not None and cindy_prev > reference:
        reference = cindy_prev
    if reference <= 0:
        reference = DAILY_SALARY * 0.55

    if urgency == 3:
        target = max(DAILY_SALARY * 0.95, reference + 6.0)
    elif scarcity == 3:
        target = max(DAILY_SALARY * 0.88, reference + 3.0)
    elif scarcity == 2 and urgency >= 2:
        target = max(DAILY_SALARY * 0.78, reference + 2.0)
    elif scarcity == 2:
        target = max(DAILY_SALARY * 0.62, min(reference + 1.5, DAILY_SALARY * 0.82))
    else:
        if urgency == 2:
            target = max(DAILY_SALARY * 0.52, min(reference, DAILY_SALARY * 0.72))
        else:
            target = DAILY_SALARY * 0.34

    if budget < DAILY_SALARY * 1.2 and urgency <= 2:
        target = min(target, DAILY_SALARY * 0.58)
    if budget < DAILY_SALARY * 0.8:
        target = min(target, budget)

    if hp >= 7 and no_water_days == 0 and scarcity == 1:
        target = min(target, DAILY_SALARY * 0.3)

    bid = max(0.0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    bid = DAILY_SALARY * 0.55

    if my_current_hp <= 2 or my_no_water_days >= 1:
        bid = DAILY_SALARY * 0.98
    elif my_current_hp <= 4:
        bid = DAILY_SALARY * 0.80
    elif my_current_hp <= 6:
        bid = DAILY_SALARY * 0.65

    if current_day >= EPISODE_DAYS - 1:
        if my_current_hp < 5:
            bid = DAILY_SALARY * 0.99
        else:
            bid = DAILY_SALARY * 0.90

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_current_hp <= 3 or my_no_water_days >= 1:
                bid = max(bid, highest_prev_bid + 5.0)
            else:
                bid = max(bid, highest_prev_bid * 0.9)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid = max(bid, average_prev_bid * 1.05)
        else:
            bid = min(bid, average_prev_bid * 1.2)
            bid = max(bid, DAILY_SALARY * 0.25)

    total_water_needed_by_alive = WATER_REQ
    for opp in alive_opponents:
        total_water_needed_by_alive += opp['water_requirement']

    if current_supply < total_water_needed_by_alive:
        if my_current_hp <= 4 or my_no_water_days >= 1:
            bid *= 1.15
        else:
            bid *= 1.05

    bid = max(1.0, bid)
    bid = min(my_current_budget, bid)

    return float(bid)

