def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Determine urgency
    if hp <= 3 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 5 or no_water_days == 1:
        urgency = 0.8
    else:
        urgency = 0.5

    # Check yesterday's bids from alive opponents
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            yesterday_bids.append(bid)

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # If someone bid very high yesterday, they might be low on budget today
        if max_prev_bid >= DAILY_SALARY * 0.9:
            if urgency < 1.0:
                # Be moderate, expect competition to be lower
                target = min(budget, DAILY_SALARY * 0.4)
                return target
            else:
                # Need water, outbid slightly
                target = min(budget, max_prev_bid * 0.9)
                return target
        else:
            # Normal competition: slightly above highest yesterday if needed
            if urgency < 0.7:
                target = min(budget, DAILY_SALARY * 0.45)
            else:
                target = min(budget, max(max_prev_bid + 2, DAILY_SALARY * urgency))
            return target
    else:
        # No trace (first day or all opponents died?)
        if urgency >= 0.8:
            return min(budget, DAILY_SALARY * 0.9)
        else:
            return min(budget, DAILY_SALARY * 0.5)

    return min(budget, DAILY_SALARY * 0.6)
